import json, os, re, subprocess, urllib.request
from datetime import datetime, timedelta, timezone
raw = os.environ["BLAND_API_KEY"].strip()
if raw.startswith("{"):
    p = json.loads(raw); raw = next((p[k] for k in ("api_key", "key", "value") if p.get(k)), raw)
CID = "b36c52d9-0ae1-426d-ab9d-1b040355e2f9"
req = urllib.request.Request("https://api.bland.ai/v1/sms/conversations/%s" % CID, headers={"Authorization": raw, "User-Agent": "mybcat-cli"})
with urllib.request.urlopen(req, timeout=60) as r:
    data = json.loads(r.read().decode()).get("data") or {}
msgs = data.get("messages") or data.get("chat_history") or []
print("NODE_NOW=%s VERSION=%s MSGS=%d" % (data.get("current_node_id"), data.get("curr_pathway_version"), len(msgs)))
mask = lambda s: re.sub(r"\d{5,}", lambda m: "***" + m.group(0)[-4:], str(s))
first_ts = None
for m in msgs:
    ts = str(m.get("created_at", ""))
    if first_ts is None and ts:
        first_ts = ts
    body = mask(str(m.get("message", m.get("content", "")))[:170]).replace(chr(10), " ")
    print("MSG %s | %s | %s" % (ts, str(m.get("sender", m.get("role", "?"))).upper()[:5], body))
vars_ = data.get("variables") or {}
for k in sorted(vars_):
    if re.search(r"preference|time_pref|appt|slot_0|from|to", str(k), re.I):
        print("VAR %s=%s" % (k, mask(str(vars_[k])[:60])))
if first_ts:
    start = datetime.fromisoformat(first_ts.replace("Z", "+00:00")) - timedelta(minutes=1)
    end = datetime.now(timezone.utc) + timedelta(minutes=1)
    out = subprocess.run(["aws", "logs", "filter-log-events", "--log-group-name", "/ecs/mott-booking-gateway", "--start-time", str(int(start.timestamp() * 1000)), "--end-time", str(int(end.timestamp() * 1000)), "--filter-pattern", "?raw_gate ?raw_fetch ?raw_resolve ?date_source ?availability ?conflict", "--query", "events[].message", "--output", "json"], capture_output=True, text=True, timeout=120)
    if out.returncode == 0:
        events = json.loads(out.stdout or "[]")
        print("GWLOG_LINES=%d" % len(events))
        for e in events[-60:]:
            print("GW", mask(str(e).strip()[:200]))
    else:
        print("GWLOG_ERROR %s" % out.stderr.strip()[:200])
print("DIAG_DONE")
PY
